std::vector<int> A = {1, 2, 5, 8};
std::vector<int> B = {2, 3, 5, 9};
std::vector<int> Result;

// Use std::back_inserter as the Output Iterator abstraction
auto out_it = std::back_inserter(Result);

// Compute symmetric difference (requires sorted input ranges)
std::set_symmetric_difference(
    A.begin(), A.end(),
    B.begin(), B.end(),
    out_it
);

// Result: {1, 3, 8, 9} (elements unique to A or B)
